shellCommands.command:
/bin/bash -lc "node - <<'NODE'
const fs = require('fs')
const html = fs.readFileSync('.next/server/app/index.html', 'utf8')
const manifest = require('./.next/prerender-manifest.json')
const checks = {
  renderingMode: manifest.routes['/']?.renderingMode,
  shellBytes: Buffer.byteLength(html),
  hasMain: html.includes('<main>'),
  hasDashboardHeading: html.includes('<h1>Dashboard</h1>'),
  hasStatsShell: html.includes('<h2>Total Revenue</h2>') && html.includes('<h2>Total Invoices</h2>'),
  hasRevenueShell: html.includes('<h2>Revenue</h2>'),
  hasInvoicesShell: html.includes('<h2>Latest Invoices</h2>'),
  hasStatus: html.includes('role=\"status\"') && html.includes('Loading dashboard data...'),
  hasOldPageSpinner: html.includes('Loading dashboard...</p>'),
}
console.log(JSON.stringify(checks, null, 2))
if (
  checks.renderingMode "'!== '"'PARTIALLY_STATIC' ||
  "'!checks.hasMain || !checks.hasDashboardHeading || !checks.hasStatsShell ||
  !checks.hasRevenueShell || !checks.hasInvoicesShell || !checks.hasStatus ||
  checks.hasOldPageSpinner
) process.exit(1)
NODE'
